-- name: ListLoans :many
SELECT id, book_id, due_on, late_fee, lent_on, loaned_at, member_id, returned_at, status
FROM loans
WHERE (sqlc.narg(status)::VARCHAR(8) IS NULL OR status = sqlc.narg(status))
  AND (sqlc.narg(member_id)::UUID IS NULL OR member_id = sqlc.narg(member_id))
ORDER BY CASE WHEN sqlc.arg(sort)::text = 'dueOn' THEN due_on END ASC,
    CASE WHEN sqlc.arg(sort)::text = '-dueOn' THEN due_on END DESC,
    CASE WHEN sqlc.arg(sort)::text = 'loanedAt' THEN loaned_at END ASC,
    CASE WHEN sqlc.arg(sort)::text = '-loanedAt' THEN loaned_at END DESC,
    id
LIMIT sqlc.arg(page_size) OFFSET sqlc.arg(page_offset);

-- name: ListLoansTotal :one
SELECT count(*) AS total
FROM loans
WHERE (sqlc.narg(status)::VARCHAR(8) IS NULL OR status = sqlc.narg(status))
  AND (sqlc.narg(member_id)::UUID IS NULL OR member_id = sqlc.narg(member_id));
